window.HOEREN_TESTS[60] = {"id":"im-fitnessstudio","name":"Im Fitnessstudio","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Mitglieder: Unser Fitnessstudio hat ab Juni neue Öffnungszeiten. Werktags nun von 6 bis 23 Uhr, also abends länger. Nicht bis 20 und nicht bis 22, werktags bis 23 Uhr. Am Wochenende bleibt es bei 8 bis 20 Uhr. Die Sauna schließt aber immer eine Stunde früher als das Studio. Viel Spaß beim Training!","gender":"f","q":"Wie lange ist das Studio werktags geöffnet?","opts":["Bis 23 Uhr.","Bis 20 Uhr.","Bis 22 Uhr."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Ich habe mich endlich im Fitnessstudio angemeldet! Aber nicht für Geräte, sondern für die Kurse — Spinning und Boxen. Sauna mag ich nicht so, ich nehme die Kurse. Möchtest du mitkommen? Erste Stunde ist gratis als Probe. Treffen wir uns Montag um 18 Uhr? Ruf zurück!","gender":"m","q":"Wofür hat sich Markus angemeldet?","opts":["Für die Geräte.","Für die Sauna.","Für die Kurse."],"correct":2},{"transcript":"Achtung Mitglieder: Wegen Wartung sind diese Woche alle Laufbänder gesperrt. Die Fahrräder und Kraftgeräte funktionieren normal. Wer laufen möchte, kann gern draußen im Park joggen — das Wetter ist schön. Ab nächstem Montag sind die Laufbänder wieder da. Danke! Vielen Dank für Ihr Verständnis und viel Spaß beim Training!","gender":"m","q":"Was ist diese Woche gesperrt?","opts":["Die Fahrräder.","Die Kraftgeräte.","Die Laufbänder."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Also, ich kündige meine Mitgliedschaft im Fitnessstudio. Nicht weil es schlecht ist — im Gegenteil. Aber ich ziehe um, zu weit weg jetzt. Zu teuer ist es nicht, wirklich nicht, nur zu weit weg nach dem Umzug. Schade, ich war gern dort. Suchst du nicht auch ein Studio? Vielleicht übernimmst du meinen Vertrag. Melde dich!","gender":"f","q":"Warum kündigt Anna?","opts":["Das Studio ist schlecht.","Sie zieht um.","Es ist zu teuer."],"correct":1},{"transcript":"Liebe Kunden: Unser neuer Trainer Stefan bietet ab Mai Personal-Training an. Eine Einzelstunde kostet 45 Euro, ein Zehnerpaket nur 400 Euro. Die erste Beratung ist kostenlos. Stefan ist Experte für Rücken und gesunde Bewegung. Termine an der Rezeption buchen! Rufen Sie an oder kommen Sie vorbei, wir beraten Sie gern!","gender":"f","q":"Was ist kostenlos?","opts":["Eine Einzelstunde.","Die erste Beratung.","Das Zehnerpaket."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was trainieren sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Das Fitnessstudio hat den Wochenplan an die Tür gehängt."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du anrufst. Ich will die Stunden fest in den Kalender schreiben."},{"speaker":"Lukas","gender":"m","text":"Ich stemme am Montag schwere Gewichte. Das Krafttraining steht fest in meinem Plan."},{"speaker":"Lisa","gender":"f","text":"Dienstag trainiere ich Spinning. Das Rad in der Gruppe macht mich richtig wach."},{"speaker":"Lukas","gender":"m","text":"Steht Pilates auch auf unserem Plan?"},{"speaker":"Lisa","gender":"f","text":"Nein. Pilates trainieren wir diese Woche nicht."},{"speaker":"Lukas","gender":"m","text":"Tom macht am Mittwoch Yoga. Er bleibt danach noch kurz auf der Matte liegen."},{"speaker":"Lisa","gender":"f","text":"Sein Rücken braucht diese ruhige Stunde wirklich."},{"speaker":"Lukas","gender":"m","text":"Sara hat nach der Schicht noch eine freie Stunde."},{"speaker":"Lisa","gender":"f","text":"Sara trainiert am Donnerstag Schwimmen. Sie schafft zwanzig Bahnen in ruhigem Tempo."},{"speaker":"Lukas","gender":"m","text":"Trainiert jemand Zumba am Abend in dem zweiten Saal?"},{"speaker":"Lisa","gender":"f","text":"Nein. Zumba machen wir auch nicht. Die Musik ist uns dort zu laut."},{"speaker":"Lukas","gender":"m","text":"Tim ist voller Energie und sucht etwas Hartes."},{"speaker":"Lisa","gender":"f","text":"Tim trainiert am Freitag Boxen. Die Handschuhe hängen schon an einem Haken."},{"speaker":"Lukas","gender":"m","text":"Dann ist unsere Trainingswoche vollständig."},{"speaker":"Lisa","gender":"f","text":"Ich packe die Sporttasche noch heute Abend."}],"options":[{"letter":"a","text":"Pilates"},{"letter":"b","text":"Zumba"},{"letter":"c","text":"Klettern"},{"letter":"d","text":"Schwimmen"},{"letter":"e","text":"Laufband"},{"letter":"f","text":"Spinning"},{"letter":"g","text":"Krafttraining"},{"letter":"h","text":"Yoga"},{"letter":"i","text":"Boxen"}],"items":[{"person":"Montag","correct":"g"},{"person":"Dienstag","correct":"f"},{"person":"Mittwoch","correct":"h"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Was kostet die Mitgliedschaft im Monat?"},{"speaker":"Trainer","gender":"m","text":"Der Basis-Tarif kostet 30 Euro, mit Kursen 45 Euro pro Monat."},{"speaker":"Kundin","gender":"f","text":"Und mit Sauna? Wären das 55 Euro?"},{"speaker":"Trainer","gender":"m","text":"Genau, mit Sauna 55 Euro im Monat. Was darf es heute sein?"},{"speaker":"Kundin","gender":"f","text":"Ich nehme den Tarif mit Kursen für 45 Euro. Ab wann gilt er?"}],"q":"Was kostet der Tarif mit Kursen?","opts":["45 Euro.","30 Euro.","55 Euro."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Entschuldigung, wo sind die Umkleidekabinen? Im ersten Stock?"},{"speaker":"Trainerin","gender":"f","text":"Nein, nicht im ersten Stock. Im Erdgeschoss, links neben der Sauna."},{"speaker":"Mann","gender":"m","text":"Und die Duschen? Im Keller vielleicht?"},{"speaker":"Trainerin","gender":"f","text":"Nein, kein Keller. Die Duschen sind gleich daneben in der Umkleide, gleich hier."},{"speaker":"Mann","gender":"m","text":"Alles klar! Erdgeschoss links. Vielen Dank und tschüss!"}],"q":"Wo sind die Umkleidekabinen?","opts":["Im ersten Stock.","Im Erdgeschoss.","Im Keller."],"correct":1},{"lines":[{"speaker":"Anfänger","gender":"m","text":"Guten Tag! Ich bin neu hier. Wie oft soll ich trainieren?"},{"speaker":"Trainer","gender":"m","text":"Am Anfang dreimal die Woche, nicht jeden Tag."},{"speaker":"Anfänger","gender":"m","text":"Nicht jeden Tag? Wirklich nicht?"},{"speaker":"Trainer","gender":"m","text":"Nein, der Körper braucht Pausen. Einmal die Woche wäre zu wenig, dreimal ist perfekt."},{"speaker":"Anfänger","gender":"m","text":"Gut, dreimal die Woche! Ab Montag geht es los!"}],"q":"Wie oft soll der Anfänger trainieren?","opts":["Jeden Tag.","Einmal die Woche.","Dreimal die Woche."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Wann ist der Zumba-Kurs? Montags?"},{"speaker":"Rezeption","gender":"f","text":"Nein, nicht montags. Dienstags und donnerstags um 19 Uhr, mit Trainerin Julia."},{"speaker":"Frau","gender":"f","text":"Und freitags? Da hätte ich Zeit."},{"speaker":"Rezeption","gender":"f","text":"Freitags gibt es leider nur Pilates am Abend, kein Zumba."},{"speaker":"Frau","gender":"f","text":"Schade! Dann komme ich dienstags und donnerstags. Bis dann, danke!"}],"q":"Wann ist Zumba?","opts":["Montags.","Dienstags und donnerstags.","Freitags."],"correct":1},{"lines":[{"speaker":"Mitglied","gender":"m","text":"Guten Tag! Mein Schließfach geht nicht auf. Nummer 42."},{"speaker":"Trainerin","gender":"f","text":"Nummer 42, alles klar. Ist sonst alles okay? Dusche warm, Geräte gut?"},{"speaker":"Mitglied","gender":"m","text":"Ja, Dusche warm und Geräte gut. Nur das Fach klemmt."},{"speaker":"Trainerin","gender":"f","text":"Gut, ich hole den Schlüssel. Einen Moment, bitte!"},{"speaker":"Mitglied","gender":"m","text":"Danke! Hoffentlich geht es schnell, ich habe Kurs."}],"q":"Welches Problem hat das Mitglied?","opts":["Das Gerät ist kaputt.","Die Dusche ist kalt.","Das Schließfach geht nicht auf."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Berg, einem Fitnesstrainer. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Berg, Sie arbeiten seit 12 Jahren als Fitnesstrainer. Warum kommen die Leute zu Ihnen?"},{"speaker":"Berg","gender":"m","text":"Sehr unterschiedlich, manche wollen abnehmen, andere Muskeln aufbauen. Aber immer mehr kommen wegen Rückenschmerzen — sie sitzen zu viel im Büro. Bewegung hilft enorm, das sehe ich jeden Tag."},{"speaker":"Reporterin","gender":"f","text":"Was ist der größte Fehler von Anfängern?"},{"speaker":"Berg","gender":"m","text":"Zu viel zu schnell. Sie trainieren die erste Woche jeden Tag, dann tut alles weh und sie hören auf. Besser langsam anfangen, dafür regelmäßig dranbleiben. Geduld ist alles im Sport."},{"speaker":"Reporterin","gender":"f","text":"Wie wichtig ist die Ernährung?"},{"speaker":"Berg","gender":"m","text":"Sehr wichtig — viele unterschätzen das. Training allein reicht nicht. Wer abnehmen will, muss auch das Essen ändern. Ich sage immer: Der Erfolg kommt zu 70 Prozent aus der Küche, nicht aus dem Studio."},{"speaker":"Reporterin","gender":"f","text":"Brauchen alle einen Personal Trainer?"},{"speaker":"Berg","gender":"m","text":"Nein, nicht alle. Am Anfang ist eine Einweisung sinnvoll, damit man die Geräte richtig benutzt. Aber später kann man gut allein trainieren. Ein Trainer lohnt sich vor allem bei besonderen Zielen oder Verletzungen."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie Menschen, die keine Zeit haben?"},{"speaker":"Berg","gender":"m","text":"Auch wenig ist besser als nichts. Zwanzig Minuten zu Hause, Treppe statt Aufzug, zu Fuß zur Arbeit. Man muss nicht immer ins Studio. Der Alltag bietet viele Chancen für Bewegung — man muss sie nur nutzen."}],"items":[{"q":"Immer mehr Menschen kommen wegen Rückenschmerzen.","correct":"ja"},{"q":"Herr Berg rät Anfängern, am Anfang jeden Tag zu trainieren.","correct":"nein"},{"q":"Für ihn ist die Ernährung sehr wichtig.","correct":"ja"},{"q":"Er meint, jeder braucht unbedingt einen Personal Trainer.","correct":"nein"},{"q":"Er empfiehlt, auch im Alltag mehr Bewegung einzubauen.","correct":"ja"}]}]};
